{
  "name": "opencode-graphiti",
  "version": "0.2.4",
  "description": "OpenCode plugin for persistent memory via Graphiti knowledge graph",
  "keywords": [
    "opencode",
    "graphiti",
    "knowledge-graph",
    "persistent-memory",
    "plugin",
    "mcp",
    "ai",
    "context"
  ],
  "author": "Vicary A. <vicary.archangel@member.mensa.org>",
  "homepage": "https://github.com/vicary/opencode-graphiti#readme",
  "repository": {
    "type": "git",
    "url": "https://github.com/vicary/opencode-graphiti.git"
  },
  "license": "MIT",
  "bugs": {
    "url": "https://github.com/vicary/opencode-graphiti/issues"
  },
  "main": "./esm/mod.js",
  "module": "./esm/mod.js",
  "types": "./esm/mod.d.ts",
  "exports": {
    ".": {
      "import": "./esm/mod.js",
      "require": "./script/mod.js"
    }
  },
  "scripts": {},
  "engines": {
    "node": ">=20"
  },
  "opencode": {
    "type": "plugin",
    "hooks": [
      "chat.message",
      "event",
      "experimental.session.compacting",
      "experimental.chat.messages.transform"
    ]
  },
  "dependencies": {
    "@opencode-ai/plugin": "1.2.26",
    "@opencode-ai/sdk": "1.2.26",
    "ioredis": "^5.7.0",
    "zod": "4.3.6",
    "@modelcontextprotocol/sdk": "^1.25.2",
    "cosmiconfig": "^9.0.0"
  },
  "devDependencies": {
    "@types/node": "^20.0.0"
  },
  "_generatedBy": "dnt@dev"
}
